"use strict";

const {platform, type} = require("os");

const supportedPlatforms = new Set([
  "aix",
  "android",
  "darwin",
  "freebsd",
  "linux",
  "openbsd",
  "sunos",
  "win"
]);

const plat = platform();

if (supportedPlatforms.has(plat)) {
  let file = plat;
  if (plat === "aix") {
    file = type() === "OS" ? "ibmi" : "sunos"; // AIX `netstat` output is compatible with Solaris
  }

  const m = require(`./${file}.js`);
  module.exports.v = () => m.v();
  module.exports.v = () => m.v();
  module.exports.v.sync = () => m.v.sync();
  module.exports.v.sync = () => m.v.sync();
} else {
  const err = new Error(`Unsupported Platform: ${plat}`);
  module.exports.v = () => Promise.reject(err);
  module.exports.v = () => Promise.reject(err);
  module.exports.v.sync = () => { throw err; };
  module.exports.v.sync = () => { throw err; };
}
